//! Matugen palette generated by DankMaterialShell from the wallpaper
//! (`~/.cache/DankMaterialShell/dms-colors.json`), watched for changes.

use std::{
    fs,
    path::PathBuf,
    time::{Duration, Instant, SystemTime},
};

use ratatui::style::Color;
use serde_json::Value;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct MatugenColors {
    pub accent: Color,
    pub on_accent: Color,
    pub surface: Color,
    pub fg: Color,
    pub muted: Color,
    pub dim: Color,
    pub warn: Color,
}

pub struct MatugenWatcher {
    path: Option<PathBuf>,
    mtime: Option<SystemTime>,
    last_check: Instant,
    pub colors: Option<MatugenColors>,
}

fn hex(value: &Value) -> Option<Color> {
    let s = value.as_str()?.trim().trim_start_matches('#');
    if s.len() < 6 {
        return None;
    }
    let r = u8::from_str_radix(&s[0..2], 16).ok()?;
    let g = u8::from_str_radix(&s[2..4], 16).ok()?;
    let b = u8::from_str_radix(&s[4..6], 16).ok()?;
    Some(Color::Rgb(r, g, b))
}

fn parse(json: &Value) -> Option<MatugenColors> {
    let mode = json["mode"].as_str().unwrap_or("dark");
    let c = &json["colors"][mode];
    let pick = |keys: &[&str]| keys.iter().find_map(|k| hex(&c[*k]));
    Some(MatugenColors {
        accent: pick(&["primary"])?,
        on_accent: pick(&["on_primary"]).unwrap_or(Color::Black),
        surface: pick(&["surface_container_high", "surface_container", "surface_variant"])?,
        fg: pick(&["on_surface", "on_background"])?,
        muted: pick(&["on_surface_variant", "outline"])?,
        dim: pick(&["outline_variant", "outline"])?,
        warn: pick(&["tertiary", "error"])?,
    })
}

impl MatugenWatcher {
    pub fn new() -> Self {
        let path = dirs::cache_dir().map(|d| d.join("DankMaterialShell").join("dms-colors.json"));
        let mut watcher = Self {
            path,
            mtime: None,
            last_check: Instant::now() - Duration::from_secs(10),
            colors: None,
        };
        watcher.poll();
        watcher
    }

    /// Re-read the palette when the file changed. Cheap: a stat every 2 s.
    pub fn poll(&mut self) -> bool {
        if self.last_check.elapsed() < Duration::from_secs(2) {
            return false;
        }
        self.last_check = Instant::now();
        let Some(path) = self.path.as_ref() else { return false };
        let mtime = fs::metadata(path).and_then(|m| m.modified()).ok();
        if mtime.is_none() || mtime == self.mtime {
            return false;
        }
        self.mtime = mtime;
        let parsed = fs::read_to_string(path)
            .ok()
            .and_then(|s| serde_json::from_str::<Value>(&s).ok())
            .and_then(|j| parse(&j));
        let changed = parsed != self.colors;
        self.colors = parsed;
        changed
    }
}
